package com.cryptoloan.pricing.adapters.out;
import com.cryptoloan.pricing.domain.port.PriceProviderPort;import java.math.BigDecimal;import java.net.URI;import java.net.http.*;import java.time.Duration;import java.util.regex.*;import org.slf4j.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;
@Component class CoinGeckoPriceAdapter implements PriceProviderPort{private static final Logger log=LoggerFactory.getLogger(CoinGeckoPriceAdapter.class);private final HttpClient client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build();private final String baseUrl;CoinGeckoPriceAdapter(@Value("${cryptoloan.pricing.coingecko-url}")String baseUrl){this.baseUrl=baseUrl;}public BigDecimal fetchEur(String id){try{URI uri=URI.create(baseUrl+"/simple/price?ids="+id+"&vs_currencies=eur");HttpRequest req=HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(5)).GET().build();HttpResponse<String> response=client.send(req,HttpResponse.BodyHandlers.ofString());Matcher m=Pattern.compile("\\\"eur\\\"\\s*:\\s*([0-9]+(?:\\.[0-9]+)?)").matcher(response.body());if(response.statusCode()==200&&m.find())return new BigDecimal(m.group(1));throw new IllegalStateException("Réponse prix invalide");}catch(Exception e){log.warn("CoinGecko indisponible pour {}, utilisation du prix de repli",id);return switch(id){case"bitcoin"->new BigDecimal("60000");case"ethereum"->new BigDecimal("3000");case"litecoin"->new BigDecimal("80");default->new BigDecimal("100");};}}}

